from api.models import Profile, Metric


class Provider(object):
    code = None

    def get_metrics(self, profile):
        raise NotImplementedError()


class Garmin(Provider):
    code = 0

    def get_metrics(self, profile):
        return [
            Metric(profile=profile, name='', value=0),
        ]


