					if board[i][j]!=0:
						l.append(board[i][j])
				print l
				for k in range(9):
					if board[i][k]==0:
						for x in l:
							if x in d[(i,k)]:
								d[(i,k)].remove(x)
						if len(d[(i,k)])==1:
							board[i][k]=d[(i,k)][0]
							d.pop((i,k),None)
			print d
		def checkcolum():
			for j in range(9):
				l=[]
				for i in range(9):
					if board[i][j]!=0:
						l.append(board[i][j])
				for k in range(9):
					if board[k][j]==0:
						for x in l:
							if x in d[(k,j)]:
								d[(k,j)].remove(x)
						if len(d[(k,j)])==1:
							board[k][j]=d[(k,j)][0]
							d.pop((k,j),None)
		def checkblock():
			for i in range(3):
				for j in range(3):
					l=[]
					for k in range(3):
						for m in range(3):
							if board[i*3+k][j*3+m]!=0:
								l.append(board[i*3+k][j*3+m])
					for n in range(3):
						for o in range(3):
							if board[i*3+n][j*3+o]==0:
								for x in l:
									if x in d[(i*3+n,j*3+o)]:
										 d[(i*3+n,j*3+o)].remove(x)
								if len( d[(i*3+n,j*3+o)])==1:
									board[i*3+n][j*3+o]=d[(i*3+n,j*3+o)][0]
									d.pop((i*3+n,j*3+o),None)
		check()
		while d:
			si=len(d)
			checkrow()
			checkcolum()
			checkblock()
			if len(d)==si:
				print board
				break

