    def __init__(self,capacity):
        self.top=-1
        self.capacity=capacity
        self.precedence={"+":1,"-":1,"*":2,"/":2,"^":3}
        self.array=[]
        self.output=[]
    def isEmpty(self):
        return True if self.top==-1 else False
        
    def push(self,x):
        self.top+=1
        self.array.append(x)
    def peek(self):
        return self.array[-1]
    def pop(self):
        if not self.isEmpty():
            self.top-=1
            return self.array.pop()
        else:
            return "$"
    def isOperand(self,ch):
        return ch.isalpha()
    def notGreater(self,i):
        try:
            a = self.precedence[i]
            b = self.precedence[self.peek()]
            
            return True if a<=b else False
        except KeyError:
            return False

    def infix(self,exp):
        for i in exp:
            if self.isOperand(i):
                self.output.append(i)

            elif i=="(":
